static bool menu_item_is_visible(const sampler_menu_item_t& item, menu_page_t page)
{
  switch (item.visibility) {
  default:
  case sampler_menu_item_t::visibility_t::always:
    return true;
  case sampler_menu_item_t::visibility_t::ble_midi:
    return external_input_mode == external_input_mode_t::ble_midi;
  case sampler_menu_item_t::visibility_t::audio_beat:
    return beat_format == beat_format_t::audio;
  case sampler_menu_item_t::visibility_t::pattern_beat:
    return beat_format == beat_format_t::pattern;
  case sampler_menu_item_t::visibility_t::editable_sample: {
    const auto source = page_settings(synth_target_for_menu_page(page)).source;
    return source == synth_tone_source_t::pad || source == synth_tone_source_t::file;
  }
  }
}

// All menu operations use this filtered list, so drawing, encoder movement and
// numeric shortcuts always share the same visible numbering.
static const sampler_menu_item_t* menu_items(menu_page_t page, size_t* count)
{
  size_t raw_count = 0;
  const auto* raw_items = menu_raw_items(page, &raw_count);
  static sampler_menu_item_t visible_items[16];
  size_t visible_count = 0;
  for (size_t i = 0; i < raw_count && visible_count < std::size(visible_items); ++i) {
    if (menu_item_is_visible(raw_items[i], page)) {
      visible_items[visible_count++] = raw_items[i];
      if (visible_items[visible_count - 1u].value == menu_value_t::background_repeat) {
        visible_items[visible_count - 1u].label = "Beat Repeat";
      }
      if (page == menu_page_t::sd_card
       && visible_items[visible_count - 1u].action == menu_action_t::sd_primary
       && !kp::storage_sd.isMounted()) {
        visible_items[visible_count - 1u].label = "Load SD Card";
      }
    }
  }
  *count = visible_count;
  return visible_count == 0 ? nullptr : visible_items;
}

