static void select_kit_wav(void)
{
  if (menu_cursor >= kit_wav_list.size()) { return; }
  const auto& f = kit_wav_list[menu_cursor];
  std::string name = f.filename;
  if (name.rfind("builtin:", 0) == 0) {
    snprintf(kit_pending_wav_path, sizeof(kit_pending_wav_path), "%s", name.c_str());
    snprintf(kit_pending_wav_name, sizeof(kit_pending_wav_name), "%s", name.c_str() + 8);
    clear_menu_preview();
    kit_edit_state = kit_shortcut_target_pad >= 0
      ? kit_edit_state_t::assign_confirm_shortcut : kit_edit_state_t::assign_wait_pad;
    menu_depth = menu_dynamic_depth();
    menu_sound_navigate(1);
    draw_menu_page_transition(1);
    draw_menu_keypad();
    return;
  }
  const size_t dot = name.find_last_of('.');
  if (dot != std::string::npos) { name.resize(dot); }
  std::string path = std::string(kit_wav_dir) + "/" + f.filename;
  snprintf(kit_pending_wav_path, sizeof(kit_pending_wav_path), "%s", path.c_str());
  snprintf(kit_pending_wav_name, sizeof(kit_pending_wav_name), "%s", name.c_str());
  clear_menu_preview();
  kit_edit_state = kit_shortcut_target_pad >= 0
    ? kit_edit_state_t::assign_confirm_shortcut : kit_edit_state_t::assign_wait_pad;
  menu_depth = menu_dynamic_depth();
  menu_sound_navigate(1);
  draw_menu_page_transition(1);
  draw_menu_keypad();
}

static void execute_pending_beat_load(beat_rec_load_mode_t mode)
{
  const pending_beat_source_t source = pending_beat_source;
  if (source == pending_beat_source_t::none) { return; }
  const uint8_t previous_swing_amount = loop_swing_amount;
  beat_rec_snapshot_t snapshot;
  const bool keep_rec = mode != beat_rec_load_mode_t::clear_rec;
  if (keep_rec) { capture_beat_rec(snapshot); }

  clear_menu_preview();
  kit_edit_state = kit_edit_state_t::idle;
  menu_page = menu_page_t::loop_bgm;
  menu_cursor = 0;
  menu_depth = menu_page_depth(menu_page);
  menu_sound_navigate(1);
  show_loading_message(source == pending_beat_source_t::sampler_pad ? "MAKING BEAT" : "LOADING BEAT");

  bool ok = false;
  bool midi_pattern = false;
  switch (source) {
  case pending_beat_source_t::builtin_pattern:
    ok = load_builtin_beat_pattern(pending_beat_pattern);
    break;
  case pending_beat_source_t::builtin_audio:
    ok = load_builtin_audio_beat(pending_beat_path);
    break;
  case pending_beat_source_t::sd_midi:
    midi_pattern = true;
    ok = load_midi_beat_file(pending_beat_path, pending_beat_name);
    break;
  case pending_beat_source_t::sd_audio:
    ok = load_audio_beat_file(pending_beat_path, pending_beat_name);
    break;
  case pending_beat_source_t::sampler_pad:
    ok = beat_pending_source_pad >= 0 && make_beat_from_sample_pad((uint8_t)beat_pending_source_pad);
    break;
  default: break;
  }
  if (ok && mode == beat_rec_load_mode_t::follow_new_beat
   && snapshot.length_fixed && beat_format == beat_format_t::audio) {
    expand_loaded_audio_beat_toward(snapshot.length_msec);
  }
  if (ok && mode == beat_rec_load_mode_t::keep_current_tempo) {
    ok = fit_loaded_beat_to_length(snapshot.length_msec);
  }
  uint8_t detected_swing_amount = previous_swing_amount;
  bool swing_analyzed = false;
  if (ok && mode != beat_rec_load_mode_t::keep_current_tempo) {
    bool swing_confident = false;
    detected_swing_amount = detect_loaded_beat_swing_amount(&swing_confident);
    // Low-confidence audio has no reliable offbeat evidence. Straight is
    // safer than importing an arbitrary groove into every retained part.
    detected_swing_amount = swing_confident
      ? quantized_swing_amount(detected_swing_amount) : 0;
    set_loop_swing_amount(detected_swing_amount, false);
    swing_analyzed = true;
  }
  if (ok && keep_rec) {
    restore_beat_rec(snapshot);
    if (mode != beat_rec_load_mode_t::keep_current_tempo) {
      // The freshly loaded Pattern already contains its source timing. Move
      // only retained user layers from the old groove to the detected one.
      reflow_recorded_events_for_swing(previous_swing_amount,
                                        detected_swing_amount, false);
    }
  }
  if (ok && mode != beat_rec_load_mode_t::keep_current_tempo) {
    fit_chop_groups_to_loop(loop_length_msec, true);
  }
  if (ok) { save_resume_kit(); }

  processing_screen_visible = false;

  // Audio/Pattern and tempo-follow are implementation details after the
  // choice has succeeded. Keep one completion message for the Beat part.
  char completion[32] = {};
  if (ok && swing_analyzed) {
    snprintf(completion, sizeof(completion), "Beat Loaded  SWING %u%%",
             (unsigned)detected_swing_amount);
  }
  show_status_message(ok ? (swing_analyzed ? completion : "Beat Loaded")
                         : (midi_pattern ? "Bad MIDI pattern" : audio_beat_error),
                      1800, false);
  pending_beat_source = pending_beat_source_t::none;
  pending_beat_path[0] = 0;
  pending_beat_name[0] = 0;
  beat_pending_source_pad = -1;
  draw_menu(true);
}

static void begin_pending_beat_load(void)
{
  bool has_chop = false;
  if (!beat_rec_has_user_events(&has_chop)) {
    execute_pending_beat_load(beat_rec_load_mode_t::follow_new_beat);
    return;
  }
  has_chop |= sampler_has_chop_groups();
  const uint32_t candidate_length = pending_audio_beat_length_msec();
  pending_beat_recommended_mode = has_chop
    && (!candidate_length || !beat_lengths_are_compatible(candidate_length, 1))
      ? beat_rec_load_mode_t::keep_current_tempo
      : beat_rec_load_mode_t::follow_new_beat;
  kit_edit_state = kit_edit_state_t::confirm_beat_rec;
  menu_cursor = (size_t)pending_beat_recommended_mode;
  menu_depth = menu_dynamic_depth();
  menu_sound_navigate(1);
  draw_menu_page_transition(1);
  draw_menu_keypad();
}

static void select_background_wav(void)
{
  if (menu_cursor >= kit_wav_list.size()) { return; }
  clear_menu_preview();
  const auto& f = kit_wav_list[menu_cursor];
  std::string name = f.filename;
  if (name.rfind("pattern:", 0) == 0) {
    pending_beat_source = pending_beat_source_t::builtin_pattern;
    pending_beat_pattern = builtin_beat_pattern_index(name.c_str() + 8);
    begin_pending_beat_load();
    return;
  }
  if (name.rfind("builtin:", 0) == 0) {
    pending_beat_source = pending_beat_source_t::builtin_audio;
    snprintf(pending_beat_path, sizeof(pending_beat_path), "%s", name.c_str());
    begin_pending_beat_load();
    return;
  }
  const bool midi_pattern = has_lower_suffix(name, ".mid") || has_lower_suffix(name, ".midi");
  const size_t dot = name.find_last_of('.');
  if (dot != std::string::npos) { name.resize(dot); }
  std::string path = std::string(kit_wav_dir) + "/" + f.filename;
  pending_beat_source = midi_pattern ? pending_beat_source_t::sd_midi : pending_beat_source_t::sd_audio;
  snprintf(pending_beat_path, sizeof(pending_beat_path), "%s", path.c_str());
  snprintf(pending_beat_name, sizeof(pending_beat_name), "%s", name.c_str());
  begin_pending_beat_load();
}

static void select_kit_file(void)
{
  if (menu_cursor >= kit_wav_list.size()) { return; }
  const auto& f = kit_wav_list[menu_cursor];
  std::string path = std::string(kit_wav_dir) + "/" + f.filename;
  clear_menu_preview();
  kit_edit_state = kit_edit_state_t::idle;
  menu_page = kit_dialog_is_beat ? menu_page_t::beat_kit : menu_page_t::kit;
  menu_cursor = kit_dialog_is_beat ? 0 : 1;
  menu_depth = menu_page_depth(menu_page);
  menu_sound_navigate(1);
  show_loading_message();
  bool ok = kit_dialog_is_beat ? load_beat_kit_file(path.c_str()) : load_kit_file(path.c_str());
  show_status_message(ok ? "Kit loaded" : "Load failed", 1600, false);
  draw_menu(true);
}

static void select_project_file(void)
{
  if (menu_cursor >= kit_wav_list.size()) { return; }
  const auto& f = kit_wav_list[menu_cursor];
  if (f.filename == builtin_project_disco) {
    const uint32_t now = M5.millis();
    if (new_project_confirm_until_msec == 0
     || (int32_t)(new_project_confirm_until_msec - now) <= 0) {
      new_project_confirm_until_msec = now + 3200;
      show_status_message("LOAD DISCO BEAT? TAP AGAIN", 3200, false);
      return;
    }
    new_project_confirm_until_msec = 0;
    clear_menu_preview();
    kit_edit_state = kit_edit_state_t::idle;
    menu_page = menu_page_t::project;
    menu_cursor = 0;
    menu_depth = menu_page_depth(menu_page);
    menu_sound_navigate(1);
    show_loading_message("LOADING DISCO BEAT");
    load_factory_start_project();
    save_resume_kit();
    repair_pitched_pad_sources();
    apply_synth_tones(true);
    schedule_internal_synth_restore(120);
    show_status_message("DISCO Beat loaded", 1800, false);
    draw_menu(true);
    return;
  }
  std::string path = std::string(kit_wav_dir) + "/" + f.filename;
  new_project_confirm_until_msec = 0;
  clear_menu_preview();
  kit_edit_state = kit_edit_state_t::idle;
  menu_page = menu_page_t::project;
  menu_cursor = 0;
  menu_depth = menu_page_depth(menu_page);
  menu_sound_navigate(1);
  show_loading_message("LOADING PROJECT");
  const bool ok = load_project_file(path.c_str());
  show_status_message(ok ? "Project loaded" : "Load failed", 1600, false);
  draw_menu(true);
}

static void select_kit_save(void)
{
  if (menu_cursor >= kit_save_candidate_count) { return; }
  const auto& candidate = kit_save_candidates[menu_cursor];
  if (!candidate.path[0]) { return; }

  kit_edit_state = kit_edit_state_t::idle;
  menu_page = kit_dialog_is_beat ? menu_page_t::beat_kit : menu_page_t::kit;
  menu_cursor = kit_dialog_is_beat ? 1 : 2;
  menu_depth = menu_page_depth(menu_page);
  menu_sound_navigate(1);
  show_loading_message("SAVING KIT");
  bool saved = kit_dialog_is_beat ? save_current_beat_kit(candidate.path)
                                  : save_current_kit(candidate.path);
  const bool saved_default = !kit_dialog_is_beat
                          && strcmp(candidate.path, sampler_default_kit_path) == 0;
  // Saving a personal default must not turn it into the current editable
  // filename. A later ordinary Save should offer New/Copy, never overwrite it.
  if (saved && !saved_default) {
    snprintf(kit_dialog_is_beat ? current_beat_kit_path : current_kit_path,
             kit_dialog_is_beat ? sizeof(current_beat_kit_path) : sizeof(current_kit_path),
             "%s", candidate.path);
  }
  char message[64];
  char saved_stem[48] = {};
  if (saved && !saved_default) { kit_path_stem(candidate.path, saved_stem, sizeof(saved_stem)); }
  snprintf(message, sizeof(message), saved ? (saved_default ? "Default saved" : "Saved: %s") : "Save failed",
           saved && !saved_default ? saved_stem : "");
  show_status_message(message, 1800, false);
  draw_menu(true);
}

static void select_project_save(void)
{
  if (menu_cursor >= kit_save_candidate_count) { return; }
  const auto& candidate = kit_save_candidates[menu_cursor];
  if (!candidate.path[0]) { return; }
  kit_edit_state = kit_edit_state_t::idle;
  menu_page = menu_page_t::project;
  menu_cursor = 1;
  menu_depth = menu_page_depth(menu_page);
  menu_sound_navigate(1);
  show_loading_message("SAVING PROJECT");
  const bool saved = save_current_project(candidate.path);
  if (saved) { snprintf(current_project_path, sizeof(current_project_path), "%s", candidate.path); }
  char message[64];
  snprintf(message, sizeof(message), saved ? "Saved: %s" : "Save failed",
           saved ? strrchr(candidate.path, '/') + 1 : "");
  show_status_message(message, 1800, false);
  draw_menu(true);
}

static bool synth_sound_surface_active(void)
{
  return current_mode == sampler_mode_t::mode_sound
      && (current_page == performance_page_t::bass
       || current_page == performance_page_t::melody
       || current_page == performance_page_t::chord);
}

static void arm_synth_sound_pad(uint8_t pad)
{
  if (!synth_sound_surface_active() || pad >= def::pad::pad_count
   || !sample_is_synth_eligible(pad)) { return; }
  sample_edit_armed_pad = pad;
  sample_edit_pending_pad = -1;
  shared_sample_assign_pad = (int8_t)pad;
  shared_sample_assign_page = current_page;
  sound_pad_release_action = sound_pad_release_action_t::none;
  set_rec_wave_pad(pad);
  request_wave_draw();
  request_pad_state_draw(pad);
}

static void assign_pending_wav_to_pad(uint8_t pad)
{
  const bool shortcut_import = kit_edit_state == kit_edit_state_t::assign_confirm_shortcut
                            && kit_shortcut_target_pad == pad;
  char error[32] = { 0 };
  clear_menu_preview();
  kit_assign_loading_pad = pad;
  // Present the target outline before the synchronous SD/decode path begins.
  draw_menu_keypad(true);
  M5.delay(45);
  show_loading_message();
  const bool beat_target = shortcut_import && kit_shortcut_target_beat;
  bool ok = strncmp(kit_pending_wav_path, "builtin:", 8) == 0
    ? load_builtin_sample_to_pad(pad, kit_pending_wav_path, beat_target)
    : load_audio_to_pad(pad, kit_pending_wav_path, kit_pending_wav_name,
                        error, sizeof(error), beat_target);
  char msg[48];
  if (ok) {
    snprintf(msg, sizeof(msg), "Assigned P%u", (unsigned)pad_display_number(pad));
    save_resume_kit();
  } else {
    snprintf(msg, sizeof(msg), "%s", error[0] ? error : "Assign failed");
  }
  if (shortcut_import && ok) {
    const bool arm_for_synth = synth_sound_surface_active();
    kit_shortcut_target_pad = -1;
    kit_shortcut_target_beat = false;
    kit_assign_loading_pad = -1;
    kit_edit_state = kit_edit_state_t::idle;
    menu_close();
    if (arm_for_synth) {
      arm_synth_sound_pad(pad);
      char ready[32];
      snprintf(ready, sizeof(ready), "SAMPLE READY: P%u",
               (unsigned)pad_display_number(pad));
      show_status_message(ready, 1200, false);
    } else {
      show_status_message(msg, 1600, false);
    }
    request_wave_draw();
    return;
  }
  // 「音源を選ぶ → パッドへ割り当てる」は連続作業なので、成功・失敗を問わず
  // 音源一覧へ一段だけ戻す。ここから別の音源を続けて選べ、Backで初めて
  // Kit > Import Sampleへ戻るため、他の単発メニューとも規則が衝突しない。
  kit_edit_state = kit_edit_state_t::select_wav;
  kit_assign_loading_pad = -1;
  menu_depth = menu_dynamic_depth();
  show_status_message(msg, 1600, false);
  draw_menu_page_transition(-1);
  draw_menu_keypad();
}

static void clear_selected_pad_sample(uint8_t pad)
{
  clear_pad_sample(pad, true);
  kit_edit_state = kit_edit_state_t::idle;
  menu_page = menu_page_t::kit_edit;
  menu_cursor = 1;
  char msg[32];
  snprintf(msg, sizeof(msg), "Cleared P%u", (unsigned)pad_display_number(pad));
  show_status_message(msg, 1600, false);
  draw_menu(true);
}

static void reset_sampler_preferences(void)
{
  loop_quantize_enabled = true;
  loop_quantize_option_index = 2;          // 32
  loop_note_off_quantize_option_index = 3; // 64
  loop_swing_amount = 0;
  audio_beat.volume_q8 = volume_q8_from_20_percent_step(4);
  audio_beat.loop_repeats = 2;
  melody_settings = { synth_tone_source_t::general_midi, factory_melody_program,
    factory_pad_sound_pad, 0, 0, 0, factory_melody_volume };
  chord_settings = { synth_tone_source_t::general_midi, factory_chord_program,
    factory_pad_sound_pad, 0, 0, 0, factory_chord_volume };
  bass_settings = { synth_tone_source_t::general_midi, factory_bass_program,
    factory_pad_sound_pad, 0, 0, 0, factory_bass_volume };
  melody_follow_harmony_key = true;
  harmony_scale = 0;
  reset_harmony_tuning(false);
  beat_volume = 100;
  beat_drum_kit = default_beat_drum_kit;
  sampler_volume = 100;
  music_track_volume = music_track_default_volume;
  std::fill(mixer_part_volume, mixer_part_volume + mixer_part_count, 100);
  std::fill(mixer_part_muted, mixer_part_muted + mixer_part_count, false);
  for (auto& snapshot : mixer_snapshot) { snapshot = mixer_snapshot_t{}; }
  mixer_pending_snapshot = -1;
  mixer_applied_snapshot = -1;
  mixer_active = false;
  mixer_held_part = -1;
  std::fill(mixer_pad_armed, mixer_pad_armed + def::pad::pad_count, false);
  std::fill(mixer_pad_adjusted, mixer_pad_adjusted + def::pad::pad_count, false);

  // FX parameters are Kit state, but Reset All must leave neither a held
  // effect nor an old mixer scene audible after the kit has been restored.
  fx_param[fx_tempo_index] = 0;
  fx_param[fx_filter_index] = -25;
  fx_param[fx_gater_index] = 50;
  fx_param[fx_crusher_index] = 50;
  fx_param[fx_repeat_index] = 0;
  fx_param[fx_delay_index] = 1; // 2 Grid
  for (uint8_t i = 0; i < 4; ++i) {
    sampler_audio_t::setFx(i, false, fx_param[i]);
  }
  fx_selected = fx_tempo_index;
  fx_target_mask = sampler_audio_t::fx_target_live;
  fx_target_pending_mask = 0;
  sampler_audio_t::setFxTargetMask(fx_target_mask);
  sampler_audio_t::setMasterDelay(false);
  sampler_audio_t::setMasterDelayFrames(fx_delay_frames());
  sampler_audio_t::setTapeStop(false);
  fx_pad_active = -1;
  fx_speed_active = false;
  fx_speed_pressed = false;
  fx_speed_returning = false;
  fx_speed_reference_active = false;
  fx_speed_reference_origin_msec = 0;
  fx_speed_reference_origin_pos_ms = 0;
  fx_speed_reference_length_ms = 0;
  fx_speed_return_started_msec = 0;
  fx_speed_return_duration_msec = 0;
  fx_speed_ratio_current_q8 = 256;
  fx_speed_ratio_target_q8 = 256;
  sampler_audio_t::setFxSpeedRatioQ8(256);
  loop_repeat_armed = false;
  loop_repeat_running = false;
  loop_repeat_release_confirm_msec = 0;

  sampler_audio_t::setFxQuantizeStepMs(loop_quantize_step_ms(loop_display_length_ms(M5.millis())));
  refresh_sample_grid_loop_intervals();
  apply_all_mixer_parts();
  if (loop_playing && audio_beat.isValid()) {
    play_audio_beat_at(loop_pos_ms(M5.millis()));
  }
}

static void start_new_project(void)
{
  // Project content is independent from device preferences. Keep Wi-Fi,
  // external input, assignments, brightness and folder choices untouched.
  stop_all_audio(false);
  clear_kit(false);
  reset_sampler_preferences();
  // A blank Project still opens with the beginner-facing default Beat kit. Keep the
  // Pattern and its duration unset so the first Beat performance defines the
  // new loop, while all twelve Sampler pads remain empty.
  start_new_pattern_beat();
  set_harmony_key(0, false);
  current_project_path[0] = 0;
  current_kit_path[0] = 0;
  repair_pitched_pad_sources();
  apply_synth_tones(true);

  // Persist the fresh workspace immediately. save_resume_kit stops the synth
  // transport while writing, so restore the factory GM parts afterwards.
  save_resume_kit();
  schedule_internal_synth_restore(120);
}

static void invalidate_sampler_sd_views(void)
{
  kp::file_manage.invalidateStorage(&kp::storage_sd);
  kit_wav_list.clear();
  kit_wav_dir[0] = 0;
  kit_pending_wav_path[0] = 0;
  kit_pending_wav_name[0] = 0;
  pending_beat_path[0] = 0;
  pending_beat_name[0] = 0;
  pending_beat_source = pending_beat_source_t::none;
  beat_pad_source_list.clear();
  clear_menu_preview();
  if (kit_edit_state != kit_edit_state_t::idle) {
    kit_edit_state = kit_edit_state_t::idle;
    menu_depth = menu_page_depth(menu_page);
    menu_cursor = 0;
  }
}

static const char* sampler_sd_busy_reason(void)
{
  if (performance_record_active || performance_record_finishing) { return "RECORDING"; }
  if (performance_record_confirm_active) { return "SAVE RECORDING"; }
  if (wifi_file_server_qr_active || sampler_web_storage_stop_requested) { return "FILE EDITOR"; }
  if (processing_screen_visible || music_load_processing) { return "FILE OPERATION"; }
  return nullptr;
}

static void eject_sampler_sd(void)
{
  const char* busy = sampler_sd_busy_reason();
  if (busy) {
    char message[48];
    snprintf(message, sizeof(message), "SD BUSY: %s", busy);
    show_status_message(message, 2200, true);
    return;
  }
  const uint32_t now = M5.millis();
  if (sd_eject_confirm_until_msec == 0
   || (int32_t)(sd_eject_confirm_until_msec - now) <= 0) {
    sd_eject_confirm_until_msec = now + 4000;
    show_status_message("EJECT SD CARD? TAP AGAIN", 4000, true);
    return;
  }
  sd_eject_confirm_until_msec = 0;
  // Music owns the only long-lived SD stream. Already decoded Sample, Audio
  // Beat, synth and Rec data remain in RAM and intentionally keep playing.
  sampler_music_player_t::end();
  invalidate_sampler_sd_views();
  const bool ejected = kp::storage_sd.ejectStorage();
  if (ejected) {
    clear_status_message(false);
    sd_safe_remove_overlay = true;
    ui_surface_exclusive = true;
    draw_sd_safe_remove_screen();
  } else {
    show_status_message("SD CARD ERROR", 2200, true);
  }
}

static void draw_sd_safe_remove_screen(void)
{
  auto& d = M5.Display;
  const uint32_t bg = 0x08100Cu;
  d.startWrite();
  d.fillScreen(bg);
  d.drawRect(0, 0, d.width(), d.height(), 0x40D890u);
  d.drawRect(1, 1, d.width() - 2, d.height() - 2, 0x40D890u);
  d.setFont(&fonts::efontJA_16_b);
  d.setTextDatum(m5gfx::textdatum_t::middle_center);
  d.setTextColor(0xB8FFD8u, bg);
  d.setTextSize(1, 2);
  d.drawString("SD CARD", d.width() / 2, d.height() / 2 - 34);
  d.setTextColor(0xFFFFFFu, bg);
  d.setTextSize(1, 2);
  d.drawString("SAFE TO REMOVE", d.width() / 2, d.height() / 2 + 10);
  d.setTextColor(0x80A898u, bg);
  d.setTextSize(1);
  d.drawString("Press any key", d.width() / 2, d.height() - 34);
  d.endWrite();
}

static void load_sampler_sd(void)
{
  const char* busy = sampler_sd_busy_reason();
  if (busy) {
    char message[48];
    snprintf(message, sizeof(message), "SD BUSY: %s", busy);
    show_status_message(message, 2200, true);
    return;
  }
  sd_eject_confirm_until_msec = 0;
  sampler_music_player_t::end();
  invalidate_sampler_sd_views();
  show_loading_message("LOADING SD CARD");
  const bool loaded = kp::storage_sd.loadStorage();
  const bool ready = loaded && ensure_sampler_sd_dirs();
  // Rebuild lists lazily on the next picker open. Do not replace the active
  // RAM Project/Kit merely because the medium may be a different card.
  invalidate_sampler_sd_views();
  show_status_message(ready ? "SD CARD READY"
                            : kp::storage_sd.mediaState() == kp::sd_media_state_t::missing
                              ? "SD CARD NOT INSERTED" : "SD CARD LOAD FAILED",
                      2200, true);
}

static void service_sampler_sd_error(void)
{
  if (!kp::storage_sd.takeMediaError()) { return; }
  sampler_music_player_t::end();
  if (performance_record_active || performance_record_finishing) {
    sampler_audio_t::stopOutputStreamCapture();
    performance_record_active = false;
    performance_record_finishing = false;
    performance_record_done = false;
    performance_record_failed = true;
    performance_record_armed = false;
    performance_record_path[0] = 0;
    request_header_draw();
  }
  if (wifi_file_server_qr_active) { stop_file_server_session("SD error"); }
  invalidate_sampler_sd_views();
  show_status_message("SD CARD ERROR - LOAD IN SYSTEM", 3200, true);
}

static void menu_execute_action(menu_action_t action)
{
  switch (action) {
  case menu_action_t::music_select:
    begin_music_file_select(menu_page_t::music_track);
    return;
  case menu_action_t::music_play_pause: {
    const auto state = sampler_music_player_t::state();
    if (state == sampler_music_player_t::state_t::idle
     || state == sampler_music_player_t::state_t::error) {
      show_status_message("Select a track", 1600, false);
      break;
    }
    sampler_music_player_t::playPause();
    show_status_message(state == sampler_music_player_t::state_t::playing
      ? "Music paused" : "Music playing", 1200, false);
    break; }
  case menu_action_t::music_rewind:
    sampler_music_player_t::seekRelative(-10);
    show_status_message("-10 sec", 900, false);
    break;
  case menu_action_t::music_forward:
    sampler_music_player_t::seekRelative(10);
    show_status_message("+10 sec", 900, false);
    break;
  case menu_action_t::music_stop:
    sampler_music_player_t::stop();
    show_status_message("Music stopped", 1200, false);
    break;
  case menu_action_t::music_remove:
    {
    const bool leave_music_page = current_page == performance_page_t::music;
    sampler_music_player_t::clear();
    normalize_fx_target_for_music_presence(false);
    menu_close();
    if (leave_music_page) {
      set_performance_page(performance_page_t::chord);
    }
    show_status_message("Music removed", 1200, false);
    return; }
  case menu_action_t::kit_load: {
    begin_kit_file_select();
    return; }
  case menu_action_t::kit_save: {
    begin_kit_save();
    return; }
  case menu_action_t::beat_kit_load: {
    begin_beat_kit_file_select();
    return; }
  case menu_action_t::beat_kit_save: {
    begin_beat_kit_save();
    return; }
  case menu_action_t::project_load:
    begin_project_file_select();
    return;
  case menu_action_t::project_save:
    begin_project_save();
    return;
  case menu_action_t::project_new: {
    const uint32_t now = M5.millis();
    if (new_project_confirm_until_msec == 0
     || (int32_t)(new_project_confirm_until_msec - now) <= 0) {
      new_project_confirm_until_msec = now + 3200;
      show_status_message("CLEAR PROJECT? TAP AGAIN", 3200, false);
      break;
    }
    new_project_confirm_until_msec = 0;
    show_loading_message("CLEARING PROJECT");
    start_new_project();
    show_status_message("Project cleared", 1800, false);
    break; }
  case menu_action_t::kit_new:
    clear_sample_kit();
    current_kit_path[0] = 0;
    show_status_message("New Sample Kit", 1600, false);
    break;
  case menu_action_t::kit_reset_builtin:
    show_loading_message();
    show_status_message(reset_default_or_builtin_kit() ? "Default kit" : "Kit reset", 1600, false);
    break;
  case menu_action_t::kit_assign_wav:
    begin_kit_assign_wav();
    return;
  case menu_action_t::kit_clear_pad:
    begin_kit_clear_pad();
    return;
  case menu_action_t::kit_clear_all_pads:
    clear_all_pad_samples();
    show_status_message("Pads cleared", 1600, false);
    break;
  case menu_action_t::kit_pad_list:
    show_kit_pad_list();
    return;
  case menu_action_t::background_load: {
    beat_select_return_cursor = 0;
    begin_background_wav_select(true, true);
    return; }
  case menu_action_t::background_load_builtin: {
    beat_select_return_cursor = 0;
    begin_background_wav_select(true, false);
    return; }
  case menu_action_t::background_load_sd: {
    beat_select_return_cursor = 1;
    begin_background_wav_select(false, true);
    return; }
  case menu_action_t::background_load_pad: {
    begin_beat_pad_select();
    return; }
  case menu_action_t::beat_kit_acoustic:
  case menu_action_t::beat_kit_dance:
  case menu_action_t::beat_kit_chiptune: {
    const beat_drum_kit_t kit = action == menu_action_t::beat_kit_dance
      ? beat_drum_kit_t::dance
      : action == menu_action_t::beat_kit_chiptune
        ? beat_drum_kit_t::chiptune : beat_drum_kit_t::acoustic;
    show_loading_message("LOADING KIT");
    const bool ok = select_builtin_beat_kit(kit);
    show_status_message(ok ? beat_drum_kit_label(kit) : "Kit error", 1600, false);
    break; }
  case menu_action_t::beat_tap_tempo:
    begin_tap_tempo();
    return;
  case menu_action_t::beat_half_speed:
  case menu_action_t::beat_double_speed: {
    const bool double_speed = action == menu_action_t::beat_double_speed;
    const bool ok = apply_beat_speed_multiplier(double_speed);
    show_status_message(ok ? (double_speed ? "TEMPO DOUBLE" : "TEMPO HALF")
                           : "TEMPO LIMIT", 1600, false);
    break; }
  case menu_action_t::beat_half_time:
  case menu_action_t::beat_double_time: {
    const bool double_time = action == menu_action_t::beat_double_time;
    const bool ok = apply_beat_time_multiplier(double_time);
    show_status_message(ok ? (double_time ? "PATTERN DOUBLE" : "PATTERN HALF")
                           : "PATTERN LIMIT", 1600, false);
    break; }
  case menu_action_t::beat_clear_pattern:
    show_status_message(clear_beat_pattern() ? "Pattern cleared" : "Beat error", 1600, false);
    break;
  case menu_action_t::background_clear:
    clear_active_beat();
    show_status_message("Beat cleared", 1600, false);
    break;
  case menu_action_t::loop_clear:
    clear_rec_data();
    show_status_message("Rec cleared", 1600, false);
    break;
  case menu_action_t::loop_save_as_bgm:
    save_loop_as_bgm();
    return;
  case menu_action_t::loop_stop:
    stop_all_audio();
    show_status_message("Stopped", 1600, false);
    break;
  case menu_action_t::input_learn:
    menu_visible = false;
    learn_state = learn_state_t::waiting_target;
    learn_target_label[0] = 0;
    learn_target = (int16_t)midi_assign_target_t::none;
    learn_target_deadline_msec = M5.millis() + learn_target_timeout_ms;
    draw_learn_overlay();
    return;
  case menu_action_t::input_assign_list:
    begin_input_assignment_list();
    return;
  case menu_action_t::input_clear_all:
    std::fill(midi_note_assign, midi_note_assign + 128, (int16_t)midi_assign_target_t::none);
    std::fill(midi_cc_assign, midi_cc_assign + 128, (int16_t)midi_assign_target_t::none);
    std::fill(external_button_assign, external_button_assign + 32, (int16_t)midi_assign_target_t::none);
    std::fill(usb_keyboard_assign, usb_keyboard_assign + 256, (int16_t)midi_assign_target_t::none);
    std::fill(usb_gamepad_assign, usb_gamepad_assign + 256, (int16_t)midi_assign_target_t::none);
    midi_note_assign_count = 0;
    external_button_assign_count = 0;
    usb_keyboard_assign_count = 0;
    usb_gamepad_assign_count = 0;
    if (loop_playing) { session_state_save_pending = true; }
    else { save_resume_kit(); }
    show_status_message("Assigns cleared", 1600, false);
    break;
  case menu_action_t::input_source_select: {
    const uint8_t selected = menu_cursor;
    if (selected >= (uint8_t)external_input_mode_t::max) { return; }
    if (selected == (uint8_t)external_input_mode) {
      menu_back();
      return;
    }
    const auto next_mode = (external_input_mode_t)selected;
    const bool needs_restart = external_input_mode_needs_restart(next_mode);
    set_external_input_mode(next_mode);
    if (!needs_restart) {
      show_status_message("Input source set", 1600, false);
      menu_back();
    }
    return; }
  case menu_action_t::ble_device_scan:
    begin_ble_device_scan();
    return;
  case menu_action_t::ble_device_forget: {
    const bool had_device = ble_preferred_address[0] != 0;
    task_midi.forgetBLEMidiPreferredDevice();
    ble_preferred_address[0] = 0;
    ble_preferred_name[0] = 0;
    save_external_input_config();
    show_status_message(had_device ? "BLE device forgotten" : "No saved device", 1800, false);
    break; }
  case menu_action_t::reset_ble_connection:
    if (external_input_mode != external_input_mode_t::ble_midi) {
      show_status_message("Select BLE MIDI first", 2000, false);
      break;
    }
    if (ble_connection_reset_state != ble_connection_reset_state_t::idle) { return; }
    task_midi.clearBLEMidiCentralBond();
    kp::system_registry->midi_port_setting.setBLEMIDI(kp::def::command::midi_off);
    ble_connection_reset_state = ble_connection_reset_state_t::stopping;
    ble_connection_reset_deadline_msec = M5.millis() + 1000;
    show_loading_message("RESETTING BLE");
    return;
  case menu_action_t::external_tone_select:
    synth_sound_select_active = false;
    kit_edit_state = kit_edit_state_t::select_external_tone;
    menu_cursor = external_midi_ch1_program;
    menu_depth = menu_dynamic_depth();
    menu_sound_navigate(1);
    menu_sound_cursor(menu_cursor + 1);
    draw_menu_page_transition(1);
    draw_menu_keypad();
    return;
  case menu_action_t::external_pad_select:
    synth_sound_select_active = false;
    kit_edit_state = kit_edit_state_t::select_external_pad;
    menu_cursor = pad_display_number(external_midi_pad) - 1;
    menu_depth = menu_dynamic_depth();
    menu_sound_navigate(1);
    menu_sound_cursor(menu_cursor + 1);
    draw_menu_page_transition(1);
    draw_menu_keypad();
    return;
  case menu_action_t::external_pad_base_note_select:
    synth_sound_select_active = false;
    if (external_midi_pad >= def::pad::pad_count || !sampler_pool_t::slot[external_midi_pad].isValid()) {
      show_status_message("Select Pad first", 1600, false);
      draw_menu(true);
      return;
    }
    kit_edit_state = kit_edit_state_t::select_external_pad_base_note;
    menu_cursor = sampler_pool_t::slot[external_midi_pad].base_note;
    menu_depth = menu_dynamic_depth();
    menu_sound_navigate(1);
    menu_sound_cursor(menu_cursor + 1);
    draw_menu_page_transition(1);
    draw_menu_keypad();
    return;
  case menu_action_t::synth_tone_select: {
    synth_menu_target = synth_target_for_menu_page(menu_page);
    synth_sound_select_active = true;
    auto& settings = page_settings(synth_menu_target);
    kit_edit_state = kit_edit_state_t::select_external_tone;
#if defined(KANPLAY_AMY_INTEGRATION) && !defined(M5UNIFIED_PC_BUILD)
    settings.program = std::min<uint8_t>(settings.program, sampler_amy_engine::tone_count - 1);
#endif
    menu_cursor = settings.program;
    preview_synth_menu_selection();
    menu_depth = menu_dynamic_depth();
    menu_sound_navigate(1);
    menu_sound_cursor(menu_cursor + 1);
    draw_menu_page_transition(1);
    draw_menu_keypad();
    return; }
  case menu_action_t::synth_pad_select: {
    synth_menu_target = synth_target_for_menu_page(menu_page);
    synth_sound_select_active = true;
    auto& settings = page_settings(synth_menu_target);
    kit_edit_state = kit_edit_state_t::select_external_pad;
    menu_cursor = pad_display_number(settings.pad) - 1;
    preview_synth_menu_selection();
    menu_depth = menu_dynamic_depth();
    menu_sound_navigate(1);
    menu_sound_cursor(menu_cursor + 1);
    draw_menu_page_transition(1);
    draw_menu_keypad();
    return; }
  case menu_action_t::synth_sample_file_select:
    begin_synth_file_select(synth_file_kind_t::sample_file);
    return;
  case menu_action_t::synth_ktsynth_select:
    begin_synth_file_select(synth_file_kind_t::kantan_synth);
    return;
  case menu_action_t::synth_pad_base_note_select: {
    synth_menu_target = synth_target_for_menu_page(menu_page);
    synth_sound_select_active = true;
    auto* source = synth_sample_slot(synth_menu_target);
    if (!source || !source->isValid()) {
      show_status_message("Select sample first", 1600, false);
      draw_menu(true);
      return;
    }
    kit_edit_state = kit_edit_state_t::select_external_pad_base_note;
    menu_cursor = source->base_note;
    menu_depth = menu_dynamic_depth();
    menu_sound_navigate(1);
    menu_sound_cursor(menu_cursor + 1);
    draw_menu_page_transition(1);
    draw_menu_keypad();
    return; }
  case menu_action_t::wifi_setup:
    // かんぷれ本体と同じAPセットアップ画面を起動する。ブラウザでSSIDと
    // パスワードを登録すると、task_wifiがNVSへ保存してSTA接続へ移行する。
    // 起動直後のバックグラウンド更新確認が走っていても、セットアップを最優先する。
    startup_update_check_pending = false;
    begin_wifi_radio_request(wifi_radio_request_t::setup_ap);
    wifi_setup_active = true;
    wifi_setup_qr_active = true;
    ui_surface_exclusive = true;
    wifi_qr_preparing = true;
    wifi_setup_waiting_for_connection = false;
    wifi_setup_connect_deadline_msec = 0;
    wifi_setup_is_wps = false;
    wifi_setup_qr_web_page = false;
    wifi_setup_qr_dirty = true;
    kp::system_registry->runtime_info.setWiFiConnectivity(
      kp::def::command::wifi_connectivity_state_t::unchecked);
    clear_status_message(false);
    draw_menu(true);
    break;
  case menu_action_t::wifi_wps:
    begin_wifi_radio_request(wifi_radio_request_t::setup_wps);
    wifi_setup_active = true;
    wifi_setup_qr_active = false;
    ui_surface_exclusive = true;
    wifi_setup_waiting_for_connection = false;
    wifi_setup_is_wps = true;
    kp::system_registry->runtime_info.setWiFiConnectivity(
      kp::def::command::wifi_connectivity_state_t::unchecked);
    draw_wifi_setup_connection_status("WPS WAITING", "Press the router WPS button");
    break;
  case menu_action_t::wifi_info: {
    char ssid[33] = {};
    if (kp::task_wifi_t::getSavedSTASSID(ssid, sizeof(ssid))) {
      char msg[48];
      snprintf(msg, sizeof(msg), "SSID: %.24s", ssid);
      show_status_message(msg, 2400, false);
    } else {
      show_status_message("Wi-Fi not configured", 2000, false);
    }
    break; }
  case menu_action_t::wifi_update:
    start_wifi_update();
    return;
  case menu_action_t::wifi_file_editor:
    // File Editor can rename/delete Music files. Close the persistent SD read
    // handle before handing filesystem ownership to the web server.
    sampler_music_player_t::end();
    start_file_editor_session();
    return;
  case menu_action_t::sd_primary:
    if (kp::storage_sd.isMounted()) { eject_sampler_sd(); }
    else { load_sampler_sd(); }
    return;
  case menu_action_t::system_info: {
    char msg[64];
    snprintf(msg, sizeof(msg), "v%d.%d.%d RAM %u%%"
      , (int)def::app::app_version_major, (int)def::app::app_version_minor, (int)def::app::app_version_patch
      , (unsigned)((sampler_pool_t::usedBytes() * 100) / sampler_pool_t::pool_budget_bytes));
    show_status_message(msg, 1600, false);
    break; }
  case menu_action_t::reset_all_settings:
    kp::system_registry->reset();
    // Samplerの入力ソースも明示的にOFFへ戻し、USB給電を残さない。
    set_external_input_mode(external_input_mode_t::off);
    // Default Kit is deliberately separate from the immutable built-in kit.
    // A factory reset removes the personal default, then restores the same
    // Built-in DISCO Beat Project used by a device with no Resume data.
    if (ensure_sampler_sd_dirs()) {
      kp::storage_sd.removeFile(sampler_default_kit_path);
      kp::storage_sd.removeFile(sampler_legacy_default_kit_path);
    }
    reset_sampler_sd_folder_selection();
    show_loading_message();
    load_factory_start_project();
    save_resume_kit();
    repair_pitched_pad_sources();
    apply_synth_tones(true);
    schedule_internal_synth_restore(120);
    show_status_message("All reset", 1600, false);
    break;
  default:
    break;
  }
  draw_menu(true);
}

static void rebuild_input_assignment_list(void)
{
  input_assignment_list.clear();
  for (uint8_t note = 0; note < 128; ++note) {
    if (midi_note_assign[note] != (int16_t)midi_assign_target_t::none) {
      input_assignment_list.push_back({ input_source_t::midi, note, midi_note_assign[note] });
    }
  }
  for (uint8_t cc = 0; cc < 128; ++cc) {
    if (midi_cc_assign[cc] != (int16_t)midi_assign_target_t::none) {
      input_assignment_list.push_back({ input_source_t::midi_cc, cc, midi_cc_assign[cc] });
    }
  }
  for (uint8_t button = 0; button < 32; ++button) {
    if (external_button_assign[button] != (int16_t)midi_assign_target_t::none) {
      input_assignment_list.push_back({ input_source_t::external, button, external_button_assign[button] });
    }
  }
  for (uint16_t key = 0; key < 256; ++key) {
    if (usb_keyboard_assign[key] != (int16_t)midi_assign_target_t::none) {
      input_assignment_list.push_back({ input_source_t::usb_keyboard, (uint8_t)key, usb_keyboard_assign[key] });
    }
  }
  for (uint16_t code = 0; code < 256; ++code) {
    if (usb_gamepad_assign[code] != (int16_t)midi_assign_target_t::none) {
      input_assignment_list.push_back({ input_source_t::usb_gamepad, (uint8_t)code, usb_gamepad_assign[code] });
    }
  }
}

static void begin_input_assignment_list(void)
{
  rebuild_input_assignment_list();
  if (input_assignment_list.empty()) {
    show_status_message("No assignments", 1600, false);
    draw_menu(true);
    return;
  }
  input_assignment_list_active = true;
  menu_cursor = 0;
  menu_depth = menu_dynamic_depth();
  menu_sound_navigate(1);
  menu_sound_cursor(1);
  draw_menu_page_transition(1);
  draw_menu_keypad();
}

static void menu_select(void)
{
  if (!menu_visible) { return; }
  if (tap_tempo_active) {
    finish_tap_tempo(true);
    return;
  }
  if (kit_edit_state == kit_edit_state_t::assign_confirm_shortcut) {
    if (kit_shortcut_target_pad >= 0 && kit_shortcut_target_pad < (int)def::pad::pad_count) {
      menu_sound_navigate(1);
      assign_pending_wav_to_pad((uint8_t)kit_shortcut_target_pad);
    }
    return;
  }
  if (input_assignment_list_active) { return; }
  if (ble_device_ui_state == ble_device_ui_state_t::list) {
    if (menu_cursor >= ble_device_count) { return; }
    ble_device_selected = menu_cursor;
    ble_device_ui_state = ble_device_ui_state_t::confirm;
    menu_cursor = 1;
    menu_depth = menu_dynamic_depth();
    menu_sound_navigate(1);
    draw_menu_header(true);
    draw_menu(true);
    return;
  }
  if (ble_device_ui_state == ble_device_ui_state_t::confirm) {
    if (menu_cursor == 0) {
      ble_device_ui_state = ble_device_ui_state_t::list;
      menu_cursor = (uint8_t)ble_device_selected;
      menu_depth = menu_dynamic_depth();
      menu_sound_navigate(2);
      draw_menu_header(true);
      draw_menu(true);
      return;
    }
    if (ble_device_selected >= ble_device_count) { return; }
    const auto& device = ble_device_list[ble_device_selected];
    snprintf(ble_preferred_address, sizeof(ble_preferred_address), "%s", device.address);
    snprintf(ble_preferred_name, sizeof(ble_preferred_name), "%s", device.name);
    ble_auto_reconnect_blocked = false;
    begin_ble_connect_resource_guard();
    task_midi.setBLEMidiPreferredDevice(
      ble_preferred_address, ble_preferred_name, true,
      (int8_t)device.address_type);
    save_external_input_config();
    ble_device_ui_state = ble_device_ui_state_t::connecting;
    // The transport intentionally waits before scanning, then may perform
    // pairing, service discovery and notification retries. Do not let the UI
    // declare failure while that bounded connection transaction is active.
    ble_device_connect_deadline_msec = M5.millis() + 30000;
    menu_page = menu_page_t::ble_device;
    menu_cursor = 0;
    menu_depth = menu_page_depth(menu_page);
    show_loading_message("CONNECTING BLE");
    draw_menu_header(true);
    draw_menu(true);
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_kit_file) {
    select_kit_file();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_kit_save) {
    select_kit_save();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_project_file) {
    select_project_file();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_project_save) {
    select_project_save();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_music_file) {
    select_music_file();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_sample_category) {
    select_sample_category();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_wav) {
    select_kit_wav();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_synth_file) {
    select_synth_file();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_bgm_wav) {
    select_background_wav();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_bgm_pad) {
    if (menu_cursor >= beat_pad_source_list.size()) { return; }
    beat_pending_source_pad = beat_pad_source_list[menu_cursor];
    clear_menu_preview();
    kit_edit_state = kit_edit_state_t::confirm_bgm_pad;
    menu_cursor = 1;
    menu_depth = menu_dynamic_depth();
    menu_sound_navigate(1);
    draw_menu_page_transition(1);
    draw_menu_keypad();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::confirm_bgm_pad) {
    if (menu_cursor == 0) {
      clear_menu_preview();
      kit_edit_state = kit_edit_state_t::select_bgm_pad;
      menu_cursor = 0;
      menu_depth = menu_dynamic_depth();
      menu_sound_navigate(2);
      draw_menu_page_transition(-1);
      draw_menu_keypad();
      return;
    }
    if (beat_pending_source_pad < 0 || beat_pending_source_pad >= (int)def::pad::pad_count) { return; }
    pending_beat_source = pending_beat_source_t::sampler_pad;
    begin_pending_beat_load();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::confirm_beat_rec) {
    execute_pending_beat_load((beat_rec_load_mode_t)std::min<size_t>(
      menu_cursor, (size_t)beat_rec_load_mode_t::clear_rec));
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_external_tone) {
    if (synth_sound_select_active) {
      auto& settings = page_settings(synth_menu_target);
      settings.program = menu_cursor;
      settings.source = synth_tone_source_t::general_midi;
      apply_synth_tones(true);
    } else {
      external_midi_ch1_program = menu_cursor;
      external_midi_sound = external_midi_sound_t::general_midi;
      apply_external_midi_ch1_tone();
    }
    save_resume_kit();
    menu_back();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_external_pad) {
    const uint8_t selected_pad = display_order_to_pad(menu_cursor);
    if (menu_cursor >= def::pad::pad_count || !sampler_pool_t::slot[selected_pad].isValid()) {
      show_status_message("Pad is empty", 1400, false);
      draw_menu(true);
      return;
    }
    if (!sample_is_synth_eligible(selected_pad)) {
      show_status_message("CHOP: SAMPLER ONLY", 1600, false);
      draw_menu(true);
      return;
    }
    if (synth_sound_select_active) {
      auto& settings = page_settings(synth_menu_target);
      settings.pad = selected_pad;
      settings.source = synth_tone_source_t::pad;
      // The selected Pad belongs to this performance page only. External MIDI
      // keeps its own sound source and therefore cannot accidentally take over
      // the SAM2695 routing when a page switches to Pad sound.
      sampler_audio_t::setOutputMuted(false);
      apply_synth_tones(true);
    } else {
      external_midi_pad = selected_pad;
      external_midi_sound = external_midi_sound_t::pad;
    }
    save_resume_kit();
    menu_back();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::select_external_pad_base_note) {
    sample_slot_t* selected_slot = synth_sound_select_active
      ? synth_sample_slot(synth_menu_target)
      : (external_midi_pad < def::pad::pad_count
          ? &sampler_pool_t::slot[external_midi_pad] : nullptr);
    if (selected_slot) {
      selected_slot->base_note = menu_cursor;
      selected_slot->base_note_auto = false;
      save_resume_kit();
    }
    menu_back();
    return;
  }
  if (kit_edit_state == kit_edit_state_t::pad_list) {
    return;
  }
  size_t count = 0;
  const auto* items = menu_items(menu_page, &count);
  if (menu_cursor >= count) { return; }
  const auto& item = items[menu_cursor];
  if (item.kind == menu_item_kind_t::submenu) {
    select_synth_source_branch(item.child);
    menu_page = item.child;
    menu_cursor = 0;
    menu_depth = menu_page_depth(menu_page);
    menu_sound_navigate(1);
    menu_sound_cursor(1);
    draw_menu_page_transition(1);
  } else if (item.kind == menu_item_kind_t::value) {
    // Values are applied live with - / +.  OK is only an acknowledgement,
    // so it never changes a setting as an accidental side effect.
    menu_sound_navigate(1);
    draw_menu_keypad();
  } else {
    menu_sound_navigate(1);
    menu_execute_action(item.action);
  }
}

static void menu_move(int diff)
{
  if (!menu_visible) { return; }
  size_t count = menu_dynamic_list_active() ? menu_dynamic_count() : 0;
  if (!menu_dynamic_list_active()) {
    menu_items(menu_page, &count);
  }
  if (count == 0) { return; }
  int old = menu_cursor;
  int next = (int)menu_cursor + diff;
  // 端ではループせずクランプする
  if (next < 0) { next = 0; }
  if (next >= (int)count) { next = (int)count - 1; }
  if (next == old) { return; }
  sd_eject_confirm_until_msec = 0;
  if (new_project_confirm_until_msec != 0) {
    new_project_confirm_until_msec = 0;
    clear_status_message(false);
  }
  if (menu_file_preview_owned) { clear_menu_preview(); }
  menu_cursor = (uint8_t)next;
  menu_sound_cursor(menu_cursor + 1);
  preview_synth_menu_selection();
  draw_menu_scroll(old, menu_cursor);
  draw_menu_keypad();
}

static void menu_input_number(uint8_t number)
{
  if (!menu_visible) { return; }
  size_t count = menu_dynamic_list_active() ? menu_dynamic_count() : 0;
  if (!menu_dynamic_list_active()) {
    menu_items(menu_page, &count);
  }
  uint8_t display_number = (number == 0) ? 10 : number;
  if (display_number < 1 || display_number > count) { return; }
  int old = menu_cursor;
  if (new_project_confirm_until_msec != 0) {
    new_project_confirm_until_msec = 0;
    clear_status_message(false);
  }
  if (menu_file_preview_owned) { clear_menu_preview(); }
  menu_cursor = display_number - 1;
  menu_sound_cursor(display_number);
  preview_synth_menu_selection();
  draw_menu_scroll(old, menu_cursor);
  draw_menu_keypad();
}

static bool menu_handle_button(int btn)
{
  if (!menu_visible || btn < 0 || btn >= 15) { return false; }
  if (tap_tempo_active) {
    const int pad = button_to_pad(btn);
    const int fn = button_to_fn(btn);
    if (pad >= 0) { tap_tempo_hit(M5.millis()); }
    else if (fn == 0) { tap_tempo_toggle_preview(); }
    else if (fn == 1) { finish_tap_tempo(true); }
    else if (fn == 2) { finish_tap_tempo(false); }
    return true;
  }
  if (input_assignment_list_active && btn == 14) {
    delete_selected_input_assignment();
    return true;
  }
  if (btn == 13 && menu_adjust_current_value(-1)) { return true; }
  if (btn == 14 && menu_adjust_current_value(1)) { return true; }
  if (btn == 14 && toggle_menu_file_preview()) { return true; }
  if (kit_edit_state == kit_edit_state_t::assign_confirm_shortcut) {
    if (btn == 4) { menu_back(); }
    else if (btn == 9 && kit_shortcut_target_pad >= 0
          && kit_shortcut_target_pad < (int)def::pad::pad_count) {
      menu_sound_navigate(1);
      assign_pending_wav_to_pad((uint8_t)kit_shortcut_target_pad);
    }
    return true;
  }
  if (kit_edit_state == kit_edit_state_t::assign_wait_pad || kit_edit_state == kit_edit_state_t::clear_wait_pad) {
    if (btn == 4) {
      menu_back();
      return true;
    }
    int pad = button_to_pad(btn);
    if (pad >= 0) {
      menu_sound_navigate(1);
      if (kit_edit_state == kit_edit_state_t::assign_wait_pad) {
        assign_pending_wav_to_pad((uint8_t)pad);
      } else {
        clear_selected_pad_sample((uint8_t)pad);
      }
      return true;
    }
  }
  switch (btn) {
  case 0: menu_input_number(1); return true;
  case 1: menu_input_number(2); return true;
  case 2: menu_input_number(3); return true;
  case 3: menu_input_number(0); return true;
  case 4: menu_close(); return true;
  case 5: menu_input_number(4); return true;
  case 6: menu_input_number(5); return true;
  case 7: menu_input_number(6); return true;
  case 8: menu_back(); return true;
  case 9: menu_select(); return true;
  case 10: menu_input_number(7); return true;
  case 11: menu_input_number(8); return true;
  case 12: menu_input_number(9); return true;
  case 13:
  case 14:
    return true;
  default: return false;
  }
}

static bool menu_handle_input(uint32_t pressed_edge)
{
  namespace bb = kp::def::button_bitmask;
  // Target selection turns every visible pad/Fn into a target. Do not let the
  // normal menu shortcuts steal Back/Exit or encoder presses in this state.
  if (learn_state == learn_state_t::waiting_target) {
    const uint32_t target_mask = 0x7FFFu
                               | bb::SUB_1 | (bb::SUB_1 << 1) | (bb::SUB_1 << 2) | (bb::SUB_1 << 3)
                               | bb::ENC1_PUSH;
    // Let target edges reach learn_capture_target(); consume all other local
    // controls so target selection cannot alter the instrument state.
    return (pressed_edge & target_mask) == 0;
  }
  if ((pressed_edge & bb::SIDE_2) && (menu_visible || learn_state != learn_state_t::idle)) {
    if (learn_state != learn_state_t::idle) {
      cancel_learn(true);
    } else if (menu_visible) {
      menu_close();
    }
    return true;
  }
  if (learn_state == learn_state_t::waiting_external) {
    // 外部入力待ちでは通常のBack/Exitを再び有効にする。
    if (pressed_edge & (1u << 8)) {
      cancel_learn(false);
      return true;
    }
    if (pressed_edge & (1u << 4)) {
      cancel_learn(true);
      return true;
    }
    if (pressed_edge & (bb::ENC1_PUSH | bb::ENC2_PUSH)) {
      menu_back();
      return true;
    }
    // Only Back/Exit are meaningful while an external event is awaited.
    return true;
  }
  if (!menu_visible && (pressed_edge & bb::ENC2_PUSH)) {
    menu_open();
    return true;
  }
  if (!menu_visible) { return false; }
  for (int btn = 0; btn < 15; ++btn) {
    if (pressed_edge & (1u << btn)) {
      menu_handle_button(btn);
      return true;
    }
  }
  if (pressed_edge & bb::ENC2_PUSH) { menu_select(); return true; }
  if (pressed_edge & bb::ENC1_PUSH) {
    // Enc1 remains Back in menus, but its global emergency-stop role must not
    // disappear just because the menu consumed the button edge.
    stop_all_audio();
    menu_back();
    return true;
  }
  return true;
}

static bool learn_capture_target(uint32_t pressed_edge)
{
  if (learn_state != learn_state_t::waiting_target || pressed_edge == 0) { return false; }
  namespace bb = kp::def::button_bitmask;
  for (int btn = 0; btn < 15; ++btn) {
    if (0 == (pressed_edge & (1u << btn))) { continue; }
    int pad = button_to_pad(btn);
    if (pad >= 0) {
      snprintf(learn_target_label, sizeof(learn_target_label), "P%d", pad_display_number((uint8_t)pad));
      learn_target = (int16_t)midi_assign_target_t::pad_base + pad;
    } else {
      int fn = button_to_fn(btn);
      if (fn < 0) { continue; }
      snprintf(learn_target_label, sizeof(learn_target_label), "Fn%d", fn + 1);
      learn_target = (int16_t)midi_assign_target_t::fn_base + fn;
    }
    learn_state = learn_state_t::waiting_external;
    learn_target_deadline_msec = M5.millis() + learn_target_timeout_ms;
    draw_learn_overlay();
    return true;
  }
  for (int i = 0; i < (int)sampler_mode_t::mode_max; ++i) {
    if (pressed_edge & (bb::SUB_1 << i)) {
      snprintf(learn_target_label, sizeof(learn_target_label), "%s", mode_info[i].name);
      learn_target = (int16_t)midi_assign_target_t::mode_base + i;
      learn_state = learn_state_t::waiting_external;
      learn_target_deadline_msec = M5.millis() + learn_target_timeout_ms;
      draw_learn_overlay();
      return true;
    }
  }
  if (pressed_edge & bb::ENC1_PUSH) {
    snprintf(learn_target_label, sizeof(learn_target_label), "STOP ALL");
    learn_target = (int16_t)midi_assign_target_t::stop_all;
    learn_state = learn_state_t::waiting_external;
    learn_target_deadline_msec = M5.millis() + learn_target_timeout_ms;
    draw_learn_overlay();
    return true;
  }
  return false;
}

static void update_midi_assign_count(void)
{
  midi_note_assign_count = 0;
  for (int note = 0; note < 128; ++note) {
    if (midi_note_assign[note] != (int16_t)midi_assign_target_t::none) { ++midi_note_assign_count; }
    if (midi_cc_assign[note] != (int16_t)midi_assign_target_t::none) { ++midi_note_assign_count; }
  }
  external_button_assign_count = 0;
  for (int button = 0; button < 32; ++button) {
    if (external_button_assign[button] != (int16_t)midi_assign_target_t::none) { ++external_button_assign_count; }
  }
  usb_keyboard_assign_count = 0;
  for (int key = 0; key < 256; ++key) {
    if (usb_keyboard_assign[key] != (int16_t)midi_assign_target_t::none) { ++usb_keyboard_assign_count; }
  }
  usb_gamepad_assign_count = 0;
  for (int code = 0; code < 256; ++code) {
    if (usb_gamepad_assign[code] != (int16_t)midi_assign_target_t::none) { ++usb_gamepad_assign_count; }
  }
}

static void delete_selected_input_assignment(void)
{
  if (!input_assignment_list_active || menu_cursor >= input_assignment_list.size()) { return; }
  const auto entry = input_assignment_list[menu_cursor];
  if (entry.source_type == input_source_t::external) {
    external_button_assign[entry.source] = (int16_t)midi_assign_target_t::none;
  } else if (entry.source_type == input_source_t::usb_keyboard) {
    usb_keyboard_assign[entry.source] = (int16_t)midi_assign_target_t::none;
  } else if (entry.source_type == input_source_t::usb_gamepad) {
    usb_gamepad_assign[entry.source] = (int16_t)midi_assign_target_t::none;
  } else if (entry.source_type == input_source_t::midi_cc) {
    midi_cc_assign[entry.source] = (int16_t)midi_assign_target_t::none;
  } else {
    midi_note_assign[entry.source] = (int16_t)midi_assign_target_t::none;
  }
  update_midi_assign_count();
  rebuild_input_assignment_list();
  if (loop_playing) { session_state_save_pending = true; }
  else { save_resume_kit(); }

  char message[32];
  const char* source = entry.source_type == input_source_t::external ? "EXT"
                     : entry.source_type == input_source_t::usb_keyboard ? "KEY"
                     : entry.source_type == input_source_t::usb_gamepad ? "PAD"
                     : entry.source_type == input_source_t::midi_cc ? "CC" : "NOTE";
  snprintf(message, sizeof(message), "%s %u deleted", source,
           (unsigned)(entry.source_type == input_source_t::external ? entry.source + 1 : entry.source));
  if (input_assignment_list.empty()) {
    input_assignment_list_active = false;
    menu_page = menu_page_t::input_assign;
    menu_cursor = 1;
    menu_depth = menu_page_depth(menu_page);
  } else if (menu_cursor >= input_assignment_list.size()) {
    menu_cursor = (uint8_t)(input_assignment_list.size() - 1);
  }
  menu_sound_navigate(1);
  show_status_message(message, 1400, false);
  draw_menu(true);
}

static void finish_learn_assign(const char* source_label, int16_t* assignment)
{
  if (learn_target == (int16_t)midi_assign_target_t::none || assignment == nullptr) { return; }
  *assignment = learn_target;
  update_midi_assign_count();
  learn_state = learn_state_t::idle;
  learn_target_deadline_msec = 0;
  menu_visible = true;
  menu_page = menu_page_t::input_assign;
  menu_cursor = 0;
  if (loop_playing) { session_state_save_pending = true; }
  else { save_resume_kit(); }
  char message[48];
  snprintf(message, sizeof(message), "%s -> %s", source_label, learn_target_label);
  show_status_message(message, 1800, false);
  draw_menu(true);
}

